			if !slicesEqual(unrecognized, tt.wantUnrecog) {
				t.Errorf("parseInjectionScanRoles(%q) unrecognized = %v, want %v", tt.raw, unrecognized, tt.wantUnrecog)
			}
		})
	}
}

